29|int
30|LLVMFuzzerTestOneInput(const char *data, size_t size) {
31|    xmlParserCtxtPtr ctxt;
32|    xmlDocPtr doc;
33|    const char *docBuffer, *docUrl;
34|    size_t maxAlloc, docSize;
35|    int opts;
36|
37|    xmlFuzzDataInit(data, size);
38|    opts = (int) xmlFuzzReadInt(4);
39|    opts |= XML_PARSE_XINCLUDE;
40|    maxAlloc = xmlFuzzReadInt(4) % (size + 100);
41|
42|    xmlFuzzReadEntities();
43|    docBuffer = xmlFuzzMainEntity(&docSize);
44|    docUrl = xmlFuzzMainUrl();
45|    if (docBuffer == NULL)
46|        goto exit;
47|
48|    /* Pull parser */
49|
50|    xmlFuzzMemSetLimit(maxAlloc);
51|    ctxt = xmlNewParserCtxt();
52|    if (ctxt != NULL) {
53|        xmlXIncludeCtxtPtr xinc;
54|        xmlDocPtr copy;
55|
56|        doc = xmlCtxtReadMemory(ctxt, docBuffer, docSize, docUrl, NULL, opts);
57|        xmlFuzzCheckMallocFailure("xmlCtxtReadMemory",
58|                                  ctxt->errNo == XML_ERR_NO_MEMORY);
59|
60|        xmlFuzzResetMallocFailed();
61|        xinc = xmlXIncludeNewContext(doc);
62|        xmlXIncludeSetFlags(xinc, opts);
63|        xmlXIncludeProcessNode(xinc, (xmlNodePtr) doc);
64|        if (doc != NULL) {
65|            xmlFuzzCheckMallocFailure("xmlXIncludeProcessNode",
66|                    xinc == NULL ||
67|                    xmlXIncludeGetLastError(xinc) == XML_ERR_NO_MEMORY);
68|        }
69|        xmlXIncludeFreeContext(xinc);
70|
71|        xmlFuzzResetMallocFailed();
72|        copy = xmlCopyDoc(doc, 1);
73|        if (doc != NULL)
74|            xmlFuzzCheckMallocFailure("xmlCopyNode", copy == NULL);
75|        xmlFreeDoc(copy);
76|
77|        xmlFreeDoc(doc);
78|        xmlFreeParserCtxt(ctxt);
79|    }
80|
81|    /* Reader */
82|
83|#ifdef LIBXML_READER_ENABLED
84|    {
85|        xmlTextReaderPtr reader;
86|        int j;
87|
88|        xmlFuzzMemSetLimit(maxAlloc);
89|        reader = xmlReaderForMemory(docBuffer, docSize, NULL, NULL, opts);
90|        if (reader == NULL)
91|            goto exit;
92|        while (xmlTextReaderRead(reader) == 1) {
93|            if (xmlTextReaderNodeType(reader) == XML_ELEMENT_NODE) {
94|                int i, n = xmlTextReaderAttributeCount(reader);
95|                for (i=0; i<n; i++) {
96|                    xmlTextReaderMoveToAttributeNo(reader, i);
97|                    while (xmlTextReaderReadAttributeValue(reader) == 1);
98|                }
99|            }
100|        }
101|        for (j = 0; j < 10; j++)
102|            xmlTextReaderRead(reader);
103|        xmlFreeTextReader(reader);
104|    }
105|#endif
106|
107|exit:
108|    xmlFuzzMemSetLimit(0);
109|    xmlFuzzDataCleanup();
110|    xmlResetLastError();
111|    return(0);
112|}
