228|static xmlXIncludeRefPtr
229|xmlXIncludeNewRef(xmlXIncludeCtxtPtr ctxt, const xmlChar *URI,
230|	          xmlNodePtr elem) {
231|    xmlXIncludeRefPtr ret;
232|
233|    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
234|    if (ret == NULL) {
235|        xmlXIncludeErrMemory(ctxt);
236|	return(NULL);
237|    }
238|    memset(ret, 0, sizeof(xmlXIncludeRef));
239|    if (URI == NULL) {
240|	ret->URI = NULL;
241|    } else {
242|	ret->URI = xmlStrdup(URI);
243|        if (ret->URI == NULL) {
244|            xmlXIncludeErrMemory(ctxt);
245|            xmlXIncludeFreeRef(ret);
246|            return(NULL);
247|        }
248|    }
249|    ret->fragment = NULL;
250|    ret->elem = elem;
251|    ret->xml = 0;
252|    ret->inc = NULL;
253|    if (ctxt->incNr >= ctxt->incMax) {
254|        xmlXIncludeRefPtr *tmp;
255|#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
256|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 1;
257|#else
258|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 4;
259|#endif
