341|static xmlChar *
342|xmlXIncludeBuildURI(xmlXIncludeCtxtPtr ctxt, xmlNodePtr cur,
343|                    const xmlChar *base, int *xmlOut) {
344|    xmlChar *href = NULL;
345|    xmlChar *parse = NULL;
346|    xmlChar *URI = NULL;
347|    int xml = 1;
348|
349|    /*
350|     * read the attributes
351|     */
352|    href = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_HREF);
353|    if (href == NULL) {
354|	href = xmlStrdup(BAD_CAST ""); /* @@@@ href is now optional */
355|	if (href == NULL) {
356|            xmlXIncludeErrMemory(ctxt);
357|	    goto error;
358|        }
359|    }
360|    parse = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE);
361|    if (parse != NULL) {
362|	if (xmlStrEqual(parse, XINCLUDE_PARSE_XML))
363|	    xml = 1;
364|	else if (xmlStrEqual(parse, XINCLUDE_PARSE_TEXT))
365|	    xml = 0;
366|	else {
367|	    xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_PARSE_VALUE,
368|	                   "invalid value %s for 'parse'\n", parse);
369|	    goto error;
370|	}
371|    }
372|
373|    /*
374|     * compute the URI
375|     */
376|    if (xmlBuildURISafe(href, base, &URI) < 0) {
377|        xmlXIncludeErrMemory(ctxt);
378|        goto error;
379|    }
380|    if (URI == NULL)
381|	xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
382|                       "failed build URL\n", NULL);
383|
384|error:
385|    xmlFree(href);
386|    xmlFree(parse);
387|    *xmlOut = xml;
388|    return(URI);
