472|/**
473| * xmlXIncludeAddNode:
474| * @ctxt:  the XInclude context
475| * @cur:  the new node
476| *
477| * Add a new node to process to an XInclude context
478| */
479|static xmlXIncludeRefPtr
480|xmlXIncludeAddNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr cur) {
481|    xmlXIncludeRefPtr ref;
482|    xmlURIPtr uri;
483|    xmlChar *URL;
484|    xmlChar *fragment = NULL;
485|    xmlChar *base;
486|    xmlChar *URI;
487|    int xml;
488|    int local = 0;
489|    int res;
490|
491|    if (ctxt == NULL)
492|	return(NULL);
493|    if (cur == NULL)
494|	return(NULL);
495|
496|    if (xmlNodeGetBaseSafe(ctxt->doc, cur, &base) < 0) {
497|        xmlXIncludeErrMemory(ctxt);
498|        return(NULL);
499|    }
500|    URI = xmlXIncludeBuildURI(ctxt, cur, base, &xml);
501|    xmlFree(base);
502|    if (URI == NULL)
503|	return(NULL);
504|    fragment = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE_XPOINTER);
505|
506|    /*
507|     * Check the URL and remove any fragment identifier
508|     */
509|    res = xmlParseURISafe((const char *)URI, &uri);
510|    if (uri == NULL) {
511|        if (res < 0)
512|            xmlXIncludeErrMemory(ctxt);
513|        else
514|            xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
515|                           "invalid value URI %s\n", URI);
516|	if (fragment != NULL)
517|	    xmlFree(fragment);
518|	xmlFree(URI);
519|	return(NULL);
520|    }
521|
522|    if (uri->fragment != NULL) {
523|        if (ctxt->legacy != 0) {
524|	    if (fragment == NULL) {
525|		fragment = (xmlChar *) uri->fragment;
526|	    } else {
527|		xmlFree(uri->fragment);
528|	    }
529|	} else {
530|	    xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_FRAGMENT_ID,
531|       "Invalid fragment identifier in URI %s use the xpointer attribute\n",
532|                           URI);
533|	    if (fragment != NULL)
534|	        xmlFree(fragment);
535|	    xmlFreeURI(uri);
536|	    xmlFree(URI);
537|	    return(NULL);
538|	}
539|	uri->fragment = NULL;
540|    }
541|    URL = xmlSaveUri(uri);
542|    xmlFreeURI(uri);
543|    if (URL == NULL) {
544|	xmlXIncludeErrMemory(ctxt);
545|	if (fragment != NULL)
546|	    xmlFree(fragment);
547|        xmlFree(URI);
548|	return(NULL);
549|    }
550|    xmlFree(URI);
551|
552|    if (xmlStrEqual(URL, ctxt->doc->URL))
553|	local = 1;
554|
555|    /*
556|     * If local and xml then we need a fragment
557|     */
558|    if ((local == 1) && (xml == 1) &&
559|        ((fragment == NULL) || (fragment[0] == 0))) {
560|	xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_RECURSION,
561|	               "detected a local recursion with no xpointer in %s\n",
562|		       URL);
563|        xmlFree(URL);
564|        xmlFree(fragment);
565|	return(NULL);
566|    }
567|
