372|/**
373| * xmlReportError:
374| * @err: the error
375| * @ctx: the parser context or NULL
376| * @str: the formatted error message
377| *
378| * Report an error with its context, replace the 4 old error/warning
379| * routines.
380| */
381|static void
382|xmlReportError(xmlParserCtxtPtr ctxt, const xmlError *err)
383|{
384|    xmlGenericErrorFunc channel;
385|    void *data;
386|    const char *message;
387|    const char *file;
388|    int line;
389|    int code;
390|    int domain;
391|    const xmlChar *name = NULL;
392|    xmlNodePtr node;
393|    xmlErrorLevel level;
394|    xmlParserInputPtr input = NULL;
395|    xmlParserInputPtr cur = NULL;
396|
397|    if (err == NULL) {
398|        if (ctxt == NULL)
399|            return;
400|        err = &ctxt->lastError;
401|    }
402|
403|    channel = xmlGenericError;
404|    data = xmlGenericErrorContext;
405|
406|    message = err->message;
407|    file = err->file;
408|    line = err->line;
409|    code = err->code;
410|    domain = err->domain;
411|    level = err->level;
412|    node = err->node;
413|
414|    if (code == XML_ERR_OK)
415|        return;
416|
417|    if ((node != NULL) && (node->type == XML_ELEMENT_NODE))
418|        name = node->name;
419|
420|    /*
421|     * Maintain the compatibility with the legacy error handling
422|     */
423|    if ((ctxt != NULL) && (ctxt->input != NULL)) {
424|        input = ctxt->input;
425|        if ((input->filename == NULL) &&
426|            (ctxt->inputNr > 1)) {
427|            cur = input;
428|            input = ctxt->inputTab[ctxt->inputNr - 2];
429|        }
430|        if (input->filename)
431|            channel(data, "%s:%d: ", input->filename, input->line);
432|        else if ((line != 0) && (domain == XML_FROM_PARSER))
433|            channel(data, "Entity: line %d: ", input->line);
434|    } else {
435|        if (file != NULL)
436|            channel(data, "%s:%d: ", file, line);
437|        else if ((line != 0) &&
438|	         ((domain == XML_FROM_PARSER) || (domain == XML_FROM_SCHEMASV)||
439|		  (domain == XML_FROM_SCHEMASP)||(domain == XML_FROM_DTD) ||
440|		  (domain == XML_FROM_RELAXNGP)||(domain == XML_FROM_RELAXNGV)))
441|            channel(data, "Entity: line %d: ", line);
442|    }
443|    if (name != NULL) {
444|        channel(data, "element %s: ", name);
445|    }
446|    switch (domain) {
447|        case XML_FROM_PARSER:
448|            channel(data, "parser ");
449|            break;
450|        case XML_FROM_NAMESPACE:
451|            channel(data, "namespace ");
452|            break;
453|        case XML_FROM_DTD:
454|        case XML_FROM_VALID:
455|            channel(data, "validity ");
456|            break;
457|        case XML_FROM_HTML:
458|            channel(data, "HTML parser ");
459|            break;
460|        case XML_FROM_MEMORY:
461|            channel(data, "memory ");
462|            break;
463|        case XML_FROM_OUTPUT:
464|            channel(data, "output ");
465|            break;
466|        case XML_FROM_IO:
467|            channel(data, "I/O ");
468|            break;
469|        case XML_FROM_XINCLUDE:
470|            channel(data, "XInclude ");
471|            break;
472|        case XML_FROM_XPATH:
473|            channel(data, "XPath ");
474|            break;
475|        case XML_FROM_XPOINTER:
476|            channel(data, "parser ");
477|            break;
478|        case XML_FROM_REGEXP:
479|            channel(data, "regexp ");
480|            break;
481|        case XML_FROM_MODULE:
482|            channel(data, "module ");
483|            break;
484|        case XML_FROM_SCHEMASV:
485|            channel(data, "Schemas validity ");
486|            break;
487|        case XML_FROM_SCHEMASP:
488|            channel(data, "Schemas parser ");
489|            break;
490|        case XML_FROM_RELAXNGP:
491|            channel(data, "Relax-NG parser ");
492|            break;
493|        case XML_FROM_RELAXNGV:
494|            channel(data, "Relax-NG validity ");
495|            break;
496|        case XML_FROM_CATALOG:
497|            channel(data, "Catalog ");
498|            break;
499|        case XML_FROM_C14N:
500|            channel(data, "C14N ");
501|            break;
502|        case XML_FROM_XSLT:
503|            channel(data, "XSLT ");
504|            break;
505|        case XML_FROM_I18N:
506|            channel(data, "encoding ");
507|            break;
508|        case XML_FROM_SCHEMATRONV:
509|            channel(data, "schematron ");
510|            break;
511|        case XML_FROM_BUFFER:
512|            channel(data, "internal buffer ");
513|            break;
514|        case XML_FROM_URI:
515|            channel(data, "URI ");
516|            break;
517|        default:
518|            break;
519|    }
520|    switch (level) {
521|        case XML_ERR_NONE:
522|            channel(data, ": ");
523|            break;
524|        case XML_ERR_WARNING:
525|            channel(data, "warning : ");
526|            break;
527|        case XML_ERR_ERROR:
528|            channel(data, "error : ");
529|            break;
530|        case XML_ERR_FATAL:
531|            channel(data, "error : ");
532|            break;
533|    }
534|    if (message != NULL) {
535|        int len;
536|	len = xmlStrlen((const xmlChar *) message);
537|	if ((len > 0) && (message[len - 1] != '\n'))
538|	    channel(data, "%s\n", message);
539|	else
540|	    channel(data, "%s", message);
541|    } else {
542|        channel(data, "%s\n", "No error message provided");
543|    }
544|
545|    if (ctxt != NULL) {
546|        xmlParserPrintFileContextInternal(input, channel, data);
547|        if (cur != NULL) {
548|            if (cur->filename)
549|                channel(data, "%s:%d: \n", cur->filename, cur->line);
550|            else if ((line != 0) && (domain == XML_FROM_PARSER))
551|                channel(data, "Entity: line %d: \n", cur->line);
552|            xmlParserPrintFileContextInternal(cur, channel, data);
553|        }
554|    }
555|    if ((domain == XML_FROM_XPATH) && (err->str1 != NULL) &&
556|        (err->int1 < 100) &&
557|	(err->int1 < xmlStrlen((const xmlChar *)err->str1))) {
558|	xmlChar buf[150];
559|	int i;
560|
561|	channel(data, "%s\n", err->str1);
562|	for (i=0;i < err->int1;i++)
563|	     buf[i] = ' ';
564|	buf[i++] = '^';
565|	buf[i] = 0;
566|	channel(data, "%s\n", buf);
567|    }
568|}
