25|int
26|LLVMFuzzerTestOneInput(const char *data, size_t size) {
27|    xmlParserCtxtPtr ctxt;
28|    htmlDocPtr doc;
29|    const char *docBuffer;
30|    size_t maxAlloc, docSize;
31|    int opts;
32|
33|    xmlFuzzDataInit(data, size);
34|    opts = (int) xmlFuzzReadInt(4);
35|    maxAlloc = xmlFuzzReadInt(4) % (size + 100);
36|
37|    docBuffer = xmlFuzzReadRemaining(&docSize);
38|    if (docBuffer == NULL) {
39|        xmlFuzzDataCleanup();
40|        return(0);
41|    }
42|
43|    /* Pull parser */
44|
45|    xmlFuzzMemSetLimit(maxAlloc);
46|    ctxt = htmlNewParserCtxt();
47|    if (ctxt != NULL) {
48|        doc = htmlCtxtReadMemory(ctxt, docBuffer, docSize, NULL, NULL, opts);
49|        xmlFuzzCheckMallocFailure("htmlCtxtReadMemory",
50|                                  ctxt->errNo == XML_ERR_NO_MEMORY);
51|
52|        if (doc != NULL) {
53|            xmlDocPtr copy;
54|
55|#ifdef LIBXML_OUTPUT_ENABLED
56|            xmlOutputBufferPtr out;
57|            const xmlChar *content;
58|
59|            /*
60|             * Also test the serializer. Call htmlDocContentDumpOutput with our
61|             * own buffer to avoid encoding the output. The HTML encoding is
62|             * excruciatingly slow (see htmlEntityValueLookup).
63|             */
64|            xmlFuzzResetMallocFailed();
65|            out = xmlAllocOutputBuffer(NULL);
66|            htmlDocContentDumpOutput(out, doc, NULL);
67|            content = xmlOutputBufferGetContent(out);
68|            xmlFuzzCheckMallocFailure("htmlDocContentDumpOutput",
69|                                      content == NULL);
70|            xmlOutputBufferClose(out);
71|#endif
72|
73|            xmlFuzzResetMallocFailed();
74|            copy = xmlCopyDoc(doc, 1);
75|            xmlFuzzCheckMallocFailure("xmlCopyNode", copy == NULL);
76|            xmlFreeDoc(copy);
77|
78|            xmlFreeDoc(doc);
79|        }
80|
81|        htmlFreeParserCtxt(ctxt);
82|    }
83|
84|
85|    /* Push parser */
86|
87|#ifdef LIBXML_PUSH_ENABLED
88|    {
89|        static const size_t maxChunkSize = 128;
90|        size_t consumed, chunkSize;
91|
92|        xmlFuzzMemSetLimit(maxAlloc);
93|        ctxt = htmlCreatePushParserCtxt(NULL, NULL, NULL, 0, NULL,
94|                                        XML_CHAR_ENCODING_NONE);
95|
96|        if (ctxt != NULL) {
97|            htmlCtxtUseOptions(ctxt, opts);
98|
99|            for (consumed = 0; consumed < docSize; consumed += chunkSize) {
100|                chunkSize = docSize - consumed;
101|                if (chunkSize > maxChunkSize)
102|                    chunkSize = maxChunkSize;
103|                htmlParseChunk(ctxt, docBuffer + consumed, chunkSize, 0);
104|            }
105|
106|            htmlParseChunk(ctxt, NULL, 0, 1);
107|            xmlFuzzCheckMallocFailure("htmlParseChunk",
108|                                      ctxt->errNo == XML_ERR_NO_MEMORY);
109|            xmlFreeDoc(ctxt->myDoc);
110|            htmlFreeParserCtxt(ctxt);
111|        }
112|    }
113|#endif
114|
115|    /* Cleanup */
116|
117|    xmlFuzzMemSetLimit(0);
118|    xmlFuzzDataCleanup();
119|    xmlResetLastError();
120|
121|    return(0);
122|}

