9699|				XML_NSMAP_FOREACH(nsMap, mi) {
9700|				    if ((mi->depth >= XML_TREE_NSMAP_PARENT) &&
9701|					(mi->shadowDepth == -1) &&
9702|					((ns->prefix == mi->newNs->prefix) ||
9703|					xmlStrEqual(ns->prefix,
9704|					mi->newNs->prefix))) {
9705|					/*
9706|					* Mark as shadowed at the current
9707|					* depth.
9708|					*/
9709|					mi->shadowDepth = depth;
9710|				    }
9711|				}
9712|			    }
9713|			    /*
9714|			    * Push mapping.
9715|			    */
