9717|				ns, cloneNs, depth) == NULL)
9718|				goto internal_error;
9719|			}
9720|		    }
9721|		}
9722|		/* cur->ns will be processed further down. */
9723|		break;
9724|	    case XML_ATTRIBUTE_NODE:
9725|		/* IDs will be processed further down. */
9726|		/* cur->ns will be processed further down. */
9727|		break;
9728|	    case XML_TEXT_NODE:
9729|	    case XML_CDATA_SECTION_NODE:
9730|		/*
9731|		* Note that this will also cover the values of attributes.
9732|		*/
