9740|		    if ((destDoc->intSubset) || (destDoc->extSubset)) {
9741|			xmlEntityPtr ent;
9742|			/*
9743|			* Different doc: Assign new entity-node if available.
9744|			*/
9745|			ent = xmlGetDocEntity(destDoc, cur->name);
9746|			if (ent != NULL) {
9747|			    clone->content = ent->content;
9748|			    clone->children = (xmlNodePtr) ent;
9749|			    clone->last = (xmlNodePtr) ent;
9750|			}
9751|		    }
9752|		} else {
9753|		    /*
9754|		    * Same doc: Use the current node's entity declaration
9755|		    * and value.
9756|		    */
9757|		    clone->content = cur->content;
9758|		    clone->children = cur->children;
9759|		    clone->last = cur->last;
9760|		}
9761|		goto leave_node;
9762|	    case XML_PI_NODE:
9763|		DICT_COPY(cur->content, clone->content);
