9771|
9772|	if (cur->ns == NULL)
9773|	    goto end_ns_reference;
9774|
9775|/* handle_ns_reference: */
9776|	/*
9777|	** The following will take care of references to ns-decls ********
9778|	** and is intended only for element- and attribute-nodes.
9779|	**
9780|	*/
9781|	if (! parnsdone) {
9782|	    if (destParent && (ctxt == NULL)) {
9783|		if (xmlDOMWrapNSNormGatherInScopeNs(&nsMap, destParent) == -1)
