9827|		/* ns-decls on curElem or on destDoc->oldNs */
9828|		destParent ? curElem : NULL,
9829|		cur->ns, &ns,
9830|		&nsMap, depth,
9831|		/* if we need to search only in the ancestor-axis */
9832|		ancestorsOnly,
