9847|	    (clone->parent != NULL))
9848|	{
9849|	    if (xmlIsID(destDoc, clone->parent, (xmlAttrPtr) clone)) {
9850|
9851|		xmlChar *idVal;
9852|
9853|		idVal = xmlNodeListGetString(cur->doc, cur->children, 1);
9854|		if (idVal != NULL) {
9855|		    if (xmlAddIDSafe(destDoc, idVal, (xmlAttrPtr) cur, 0,
9856|                                     NULL) < 0) {
9857|			/* TODO: error message. */
9858|			xmlFree(idVal);
9859|			goto internal_error;
9860|		    }
9861|		    xmlFree(idVal);
9862|		}
9863|	    }
9864|	}
9865|	/*
9866|	**
9867|	** The following will traverse the tree **************************
9868|	**
9869|	*
9870|	* Walk the element's attributes before descending into child-nodes.
9871|	*/
9872|	if ((cur->type == XML_ELEMENT_NODE) && (cur->properties != NULL)) {
9873|	    prevClone = NULL;
9874|	    parentClone = clone;
9875|	    cur = (xmlNodePtr) cur->properties;
9876|	    continue;
9877|	}
9878|into_content:
9879|	/*
9880|	* Descend into child-nodes.
9881|	*/
9882|	if (cur->children != NULL) {
9883|	    if (deep || (cur->type == XML_ATTRIBUTE_NODE)) {
9884|		prevClone = NULL;
9885|		parentClone = clone;
9886|		cur = cur->children;
9887|		continue;
9888|	    }
9889|	}
9890|
9891|leave_node:
9892|	/*
9893|	* At this point we are done with the node, its content
9894|	* and an element-nodes's attribute-nodes.
9895|	*/
