9897|	    break;
9898|	if ((cur->type == XML_ELEMENT_NODE) ||
9899|	    (cur->type == XML_XINCLUDE_START) ||
9900|	    (cur->type == XML_XINCLUDE_END)) {
9901|	    /*
9902|	    * TODO: Do we expect nsDefs on XML_XINCLUDE_START?
9903|	    */
9904|	    if (XML_NSMAP_NOTEMPTY(nsMap)) {
9905|		/*
9906|		* Pop mappings.
9907|		*/
