9909|		    (nsMap->last->depth >= depth))
9910|		{
9911|		    XML_NSMAP_POP(nsMap, mi)
9912|		}
9913|		/*
9914|		* Unshadow.
9915|		*/
9916|		XML_NSMAP_FOREACH(nsMap, mi) {
9917|		    if (mi->shadowDepth >= depth)
9918|			mi->shadowDepth = -1;
9919|		}
9920|	    }
9921|	    depth--;
9922|	}
