9924|	    prevClone = clone;
9925|	    cur = cur->next;
9926|	} else if (cur->type != XML_ATTRIBUTE_NODE) {
9927|	    /*
9928|	    * Set clone->last.
9929|	    */
9930|	    if (clone->parent != NULL)
9931|		clone->parent->last = clone;
9932|	    clone = clone->parent;
9933|	    if (clone != NULL)
9934|		parentClone = clone->parent;
9935|	    /*
9936|	    * Process parent --> next;
9937|	    */
9938|	    cur = cur->parent;
9939|	    goto leave_node;
