9941|	    /* This is for attributes only. */
9942|	    clone = clone->parent;
9943|	    parentClone = clone->parent;
9944|	    /*
9945|	    * Process parent-element --> children.
9946|	    */
9947|	    cur = cur->parent;
9948|	    goto into_content;
9949|	}
9950|    }
9951|    goto exit;
9952|
9953|internal_error:
9954|    ret = -1;
9955|
9956|exit:
9957|    /*
9958|    * Cleanup.
9959|    */
9960|    if (nsMap != NULL) {
9961|	if ((ctxt) && (ctxt->namespaceMap == nsMap)) {
9962|	    /*
9963|	    * Just cleanup the map but don't free.
9964|	    */
9965|	    if (nsMap->first) {
9966|		if (nsMap->pool)
9967|		    nsMap->last->next = nsMap->pool;
9968|		nsMap->pool = nsMap->first;
9969|		nsMap->first = NULL;
9970|	    }
9971|	} else
9972|	    xmlDOMWrapNsMapFree(nsMap);
9973|    }
9974|    /*
9975|    * TODO: Should we try a cleanup of the cloned node in case of a
