114|/**
115| * xmlCharStrdup:
116| * @cur:  the input char *
117| *
118| * a strdup for char's to xmlChar's
119| *
120| * Returns a new xmlChar * or NULL
121| */
122|
123|xmlChar *
124|xmlCharStrdup(const char *cur) {
125|    const char *p = cur;
126|
