330| *
331| * Returns the xmlChar * for the first occurrence or NULL.
332| */
333|
334|const xmlChar *
335|xmlStrchr(const xmlChar *str, xmlChar val) {
336|    if (str == NULL) return(NULL);
337|    while (*str != 0) { /* non input consuming */
338|        if (*str == val) return((xmlChar *) str);
339|        str++;
340|    }
341|    return(NULL);
