497|    if (len < 0) {
498|        len = xmlStrlen(str2);
499|        if (len < 0)
500|            return(NULL);
501|    }
502|    if ((str2 == NULL) || (len == 0))
503|        return(xmlStrdup(str1));
504|    if (str1 == NULL)
505|        return(xmlStrndup(str2, len));
506|
507|    size = xmlStrlen(str1);
508|    if ((size < 0) || (size > INT_MAX - len))
509|        return(NULL);
510|    ret = (xmlChar *) xmlMalloc((size_t) size + len + 1);
511|    if (ret == NULL)
512|        return(NULL);
